SET @qfin = LAST_INSERT_ID();

INSERT INTO quizzes (lesson_id, question, option_a, option_b, option_c, option_d, correct_answer, explanation, sort_order) VALUES
(@qfin, 'Jaký je rozdíl mezi any a unknown?', 'Žádný', 'any vypne kontrolu, unknown vyžaduje ověření typu', 'unknown je podtyp any', 'any je bezpečnější', 'b', 'unknown je type-safe alternativa k any — před použitím musíš ověřit typ pomocí typeof nebo instanceof.', 1),
(@qfin, 'Co dělá interface VeVitUser { avatar?: string; }?', 'Přidá povinný avatar', 'avatar je volitelný — může být undefined', 'avatar je readonly', 'avatar je vždy null', 'b', 'Otazník (?) označuje volitelnou vlastnost — hodnota může být undefined.', 2),
(@qfin, 'K čemu slouží generika v TypeScriptu?', 'K vytváření chyb', 'K psaní opakovaně použitelného kódu s různými typy', 'Ke zrychlení kompilace', 'K mazání typů', 'b', 'Generika umožňují definovat funkce a třídy, které pracují s různými typy při zachování typové bezpečnosti.', 3),
(@qfin, 'Co vypíše type Result = string extends number ? "yes" : "no"?', '"yes"', '"no"', 'Error', 'undefined', 'b', 'String nepatří do number — podmínka je false, výsledek je "no".', 4),
(@qfin, 'Co je Partial<Course>?', 'Course bez žádných vlastností', 'Course se všemi volitelnými vlastnostmi', 'Course jen s povinnými vlastnostmi', 'Course jen s readonly vlastnostmi', 'b', 'Partial<T> převede všechny vlastnosti typu T na volitelné (optional).', 5),
(@qfin, 'K čemu slouží .d.ts soubory?', 'K zápisu implementace funkcí', 'K deklaraci typů bez implementace', 'K testování', 'Ke konfiguraci kompilátoru', 'b', '.d.ts soubory deklarují typy (interfaces, funkce) bez implementace — popisují JS knihovny.', 6),
(@qfin, 'Co dělá Zod ve výrazu z.infer<typeof schema>?', 'Spustí schema', 'Odvodí TypeScript typ ze Zod schématu', 'Vytvoří nové schema', 'Validuje data', 'b', 'z.infer<typeof schema> extrahuje TypeScript typ z definice Zod schématu.', 7),
(@qfin, 'Jaký je správný typ pro catch (err: ...) v TypeScriptu?', 'any', 'Error', 'unknown', 'string', 'c', 'Od TS 4.4 je unknown doporučený typ pro chyby v catch — vyžaduje ověření typu před použitím.', 8),
(@qfin, 'Co je discriminated union v TypeScriptu?', 'Sjednocení dvou typů', 'Typ sjednocení se společnou vlastností pro rozlišení variant', 'Průnik typů', 'Mapped type', 'b', 'Discriminated union používá společnou vlastnost (např. status nebo ok) k rozlišení variant typu.', 9),
(@qfin, 'Co dělá tsc --strict?', 'Zapne pouze noImplicitAny', 'Zapne všechny striktní kontrolory typů najednou', 'Zpomalí kompilaci', 'Vypne typovou kontrolu', 'b', 'strict: true zapne strictNullChecks, noImplicitAny, noImplicitThis a další striktní kontroly.', 10);


